#!/bin/bash
# final.sh <tag> [plate sizes]: the final re-measure with src_v3: the Table 5 lattices (t5.sh, FINAL3 route; baseline
# docs/paper_p1/review_r1/results/X6_final/remeasure_20261017), one analysis of the ST20 plates (scale.sh -> plate.sh;
# layouts of 162+ cells generated by gen_hlat.py), then the 92-cell hlat554 (no src_v2 baseline; shared operators).
TAG=$1; SIZES=${2:-"24 51 88 110 135 162 190"}
W=/root/autodl-tmp/OPL/V3W; S=$W/scripts
for L in hlat221a hlat221b hlat222 hlat331; do bash $S/t5.sh $TAG $L; done
OPL_V3_PIPE_BODIES=0 bash $S/scale.sh $TAG "$SIZES"                        # analysis time without body generation
bash $S/t5.sh $TAG hlat554
echo "$(date +%F_%T) FINAL_${TAG}_DONE" >> $W/status.txt
